              </div>
          </div>
      )}

      {/* SIDEBAR */}
      <div className="w-80 bg-slate-50 border-r border-slate-200 flex flex-col">
        <div className="h-16 flex items-center justify-between px-6 border-b border-slate-200 bg-white">
