const __dirname = path.dirname(__filename);

const PORT = 8000;
const MONGO_URI = process.env.MONGO_URI || 'mongodb://admin:secret123@mongo:27017/whatsdoc?authSource=admin';
const ADMIN_PASS = 'secret123'; // Simple password for now

// --- APP SETUP ---
