import React, { useState, useEffect } from 'react';
import { User, Video, Check, Loader2, ChevronLeft, Image as ImageIcon, Film, Calendar } from 'lucide-react';
import { registerCustomer, getEvents } from '../services/api';
import { Link } from 'react-router-dom';
import { Event } from '../types';

const MobileRegister: React.FC = () => {
  const [formData, setFormData] = useState({ name: '', phone: '', videoName: '', fileType: 'video' as 'video'|'photo', eventId: '' });
  const [status, setStatus] = useState<'idle' | 'submitting' | 'success'>('idle');
  const [events, setEvents] = useState<Event[]>([]);
  const [loadingEvents, setLoadingEvents] = useState(true);

  useEffect(() => {
      const loadEvents = async () => {
          const data = await getEvents();
          setEvents(data);
          // Default to first active event if exists
          const active = data.find(e => e.isActive);
          if (active) {
              setFormData(prev => ({ ...prev, eventId: active.id }));
          } else if (data.length > 0) {
              setFormData(prev => ({ ...prev, eventId: data[0].id }));
          }
          setLoadingEvents(false);
      };
      loadEvents();
  }, []);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.name || !formData.phone || !formData.videoName) return;

    // Safety check for event
    if (events.length > 0 && !formData.eventId) {
        alert("Please select an event");
        return;
    }

    setStatus('submitting');

    // Clean input and remove non-numeric chars
    let cleanPhone = formData.phone.replace(/[^0-9]/g, '');

    // Remove leading zero if user typed it (e.g. 077... -> 77...)
    if (cleanPhone.startsWith('0')) {
        cleanPhone = cleanPhone.substring(1);
    }

    // Default country code: 94
    const finalPhone = '94' + cleanPhone;

    // Logic to append extension automatically
    let finalFileName = formData.videoName;
    const ext = formData.fileType === 'photo' ? '.jpg' : '.mp4';

    // Check if filename already ends with the correct extension
    if (!finalFileName.toLowerCase().endsWith(ext)) {
        finalFileName = finalFileName + ext;
    }

    const success = await registerCustomer(
        formData.name, 
        finalPhone, 
        finalFileName, 
        formData.fileType,
        formData.eventId
    );

    if (success) {
      setStatus('success');
      setTimeout(() => {
        // Keep event and filetype, reset others
        setFormData(prev => ({ ...prev, name: '', phone: '', videoName: '' })); 
        setStatus('idle');
      }, 3000);
    } else {
      alert("Failed to register. Please try again.");
      setStatus('idle');
    }
  };

  if (status === 'success') {
    return (
      <div className="fixed inset-0 z-50 bg-black/60 backdrop-blur-xl flex flex-col items-center justify-center p-6 text-center animate-in fade-in duration-300">
        <div className="bg-white/10 border border-white/20 p-8 rounded-full shadow-2xl mb-8 scale-110">
          <Check className="w-16 h-16 text-green-400 drop-shadow-lg" />
        </div>
        <h2 className="text-3xl font-bold text-white mb-3 tracking-tight">Registered!</h2>
        <p className="text-slate-300 text-lg max-w-xs mx-auto leading-relaxed">
          We'll send the {formData.fileType} to {formData.name} soon.
        </p>
      </div>
    );
  }

  return (
    <div className="min-h-screen flex flex-col bg-gray-50">

      {/* iOS Header */}
      <div className="pt-12 pb-4 px-6 flex items-center justify-between bg-white/80 backdrop-blur-md sticky top-0 z-40 border-b border-gray-200/50">
        <Link to="/" className="p-2 -ml-2 text-blue-500 font-medium flex items-center">
           <ChevronLeft className="w-5 h-5 mr-1" /> Home
        </Link>
        <span className="font-semibold text-slate-900">New Registration</span>
        <div className="w-8"></div>
      </div>

      <div className="flex-1 p-6 pb-20">
        <div className="max-w-md mx-auto space-y-8">

          <div className="text-center space-y-2 mt-4">
             <div className="w-16 h-16 bg-blue-100 rounded-2xl flex items-center justify-center mx-auto mb-4 shadow-sm text-blue-600">
               <User className="w-8 h-8" />
             </div>
             <h1 className="text-2xl font-bold text-slate-900">Customer Details</h1>
             <p className="text-slate-500">Enter information to queue the file.</p>
          </div>

          <form onSubmit={handleSubmit} className="space-y-6">

            {/* Event Selector */}
            {!loadingEvents && events.length > 0 && (
                <div className="space-y-2">
                    <label className="text-xs font-semibold text-slate-500 uppercase tracking-wider ml-1">Select Event</label>
                    <div className="relative">
                        <Calendar className="absolute left-4 top-1/2 -translate-y-1/2 w-5 h-5 text-slate-400" />
                        <select 
                            value={formData.eventId}
                            onChange={(e) => setFormData({...formData, eventId: e.target.value})}
                            className="w-full pl-12 pr-4 py-4 bg-white border-2 border-slate-100 rounded-2xl text-slate-900 font-medium focus:border-blue-500 focus:ring-4 focus:ring-blue-500/10 transition-all appearance-none outline-none"
                        >
                            {events.map(ev => (
                                <option key={ev.id} value={ev.id}>{ev.name}</option>
                            ))}
                        </select>
                    </div>
                </div>
            )}

            <div className="space-y-2">
              <label className="text-xs font-semibold text-slate-500 uppercase tracking-wider ml-1">Full Name</label>
              <div className="relative group">
                <User className="absolute left-4 top-1/2 -translate-y-1/2 w-5 h-5 text-slate-400 group-focus-within:text-blue-500 transition-colors" />
                <input
                  type="text"
                  required
                  placeholder="e.g. John Doe"
                  className="w-full pl-12 pr-4 py-4 bg-white border-2 border-slate-100 rounded-2xl text-lg font-medium placeholder:text-slate-300 focus:border-blue-500 focus:ring-4 focus:ring-blue-500/10 transition-all outline-none"
                  value={formData.name}
                  onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                />
              </div>
            </div>

            <div className="space-y-2">
              <label className="text-xs font-semibold text-slate-500 uppercase tracking-wider ml-1">WhatsApp Number</label>
              <div className="relative group">
                <span className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400 font-medium text-lg group-focus-within:text-blue-500 transition-colors">🇱🇰</span>
                <input
                  type="tel"
                  required
                  placeholder="77 123 4567"
                  className="w-full pl-12 pr-4 py-4 bg-white border-2 border-slate-100 rounded-2xl text-lg font-medium placeholder:text-slate-300 focus:border-blue-500 focus:ring-4 focus:ring-blue-500/10 transition-all outline-none font-mono"
                  value={formData.phone}
                  onChange={(e) => setFormData({ ...formData, phone: e.target.value })}
                />
              </div>
            </div>

            <div className="space-y-2">
               <label className="text-xs font-semibold text-slate-500 uppercase tracking-wider ml-1">File Type</label>
               <div className="grid grid-cols-2 gap-3">
                   <button
                     type="button"
                     onClick={() => setFormData({...formData, fileType: 'video'})}
                     className={`py-3 px-4 rounded-xl flex items-center justify-center gap-2 font-medium transition-all ${formData.fileType === 'video' ? 'bg-blue-600 text-white shadow-lg shadow-blue-500/30' : 'bg-white border-2 border-slate-100 text-slate-600'}`}
                   >
                       <Film className="w-5 h-5" /> Video (.mp4)
                   </button>
                   <button
                     type="button"
                     onClick={() => setFormData({...formData, fileType: 'photo'})}
                     className={`py-3 px-4 rounded-xl flex items-center justify-center gap-2 font-medium transition-all ${formData.fileType === 'photo' ? 'bg-purple-600 text-white shadow-lg shadow-purple-500/30' : 'bg-white border-2 border-slate-100 text-slate-600'}`}
                   >
                       <ImageIcon className="w-5 h-5" /> Photo (.jpg)
                   </button>
               </div>
            </div>

            <div className="space-y-2">
              <label className="text-xs font-semibold text-slate-500 uppercase tracking-wider ml-1">File Name</label>
              <div className="relative group">
                <Video className="absolute left-4 top-1/2 -translate-y-1/2 w-5 h-5 text-slate-400 group-focus-within:text-blue-500 transition-colors" />
                <input
                  type="text"
                  required
                  placeholder="e.g. 001"
                  className="w-full pl-12 pr-4 py-4 bg-white border-2 border-slate-100 rounded-2xl text-lg font-medium placeholder:text-slate-300 focus:border-blue-500 focus:ring-4 focus:ring-blue-500/10 transition-all outline-none font-mono"
                  value={formData.videoName}
                  onChange={(e) => setFormData({ ...formData, videoName: e.target.value })}
                />
                <div className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-400 text-sm font-bold bg-slate-100 px-2 py-1 rounded">
                    {formData.fileType === 'photo' ? '.JPG' : '.MP4'}
                </div>
              </div>
            </div>

            <button
              type="submit"
              disabled={status === 'submitting'}
              className="w-full py-4 bg-blue-600 hover:bg-blue-700 active:scale-[0.98] text-white font-bold text-lg rounded-2xl shadow-xl shadow-blue-500/20 transition-all disabled:opacity-70 disabled:cursor-not-allowed flex items-center justify-center"
            >
              {status === 'submitting' ? (
                <Loader2 className="w-6 h-6 animate-spin" />
              ) : (
                <>Register Customer</>
              )}
            </button>
          </form>
        </div>
      </div>
    </div>
  );
};

export default MobileRegister;

import React, { useState, useEffect, useCallback } from 'react';
import { UploadCloud, CheckCircle, RefreshCw, FileVideo, Loader2, Search, ArrowLeft, Filter, Layers, AlertCircle, HardDrive, Trash2, Send, Wifi, WifiOff, QrCode, LogOut, RotateCw, Calendar, Plus, Image as ImageIcon } from 'lucide-react';
import { CustomerRequest, Event } from '../types';
import { getPendingRequests, getFailedRequests, uploadDocument, getServerFiles, deleteServerFile, retryServerFile, deleteRequest, ServerFile, getWhatsAppStatus, WhatsAppStatus, getEvents, createEvent, getCompletedRequests } from '../services/api';
import { useNavigate } from 'react-router-dom';

type TabView = 'queue' | 'issues' | 'sent' | 'storage';

const DesktopDashboard: React.FC = () => {
  const [requests, setRequests] = useState<CustomerRequest[]>([]);
  const [failedRequests, setFailedRequests] = useState<CustomerRequest[]>([]);
  const [completedRequests, setCompletedRequests] = useState<CustomerRequest[]>([]);
  const [serverFiles, setServerFiles] = useState<ServerFile[]>([]);
  const [events, setEvents] = useState<Event[]>([]);
  const [selectedEventId, setSelectedEventId] = useState<string>(''); // '' means All Events

  const [isLoading, setIsLoading] = useState(false);
  const [activeTab, setActiveTab] = useState<TabView>('queue');

  // Create Event Modal
  const [showCreateEvent, setShowCreateEvent] = useState(false);
  const [newEventName, setNewEventName] = useState('');

  // Connection Status
  const [waStatus, setWaStatus] = useState<WhatsAppStatus>({ status: 'INITIALIZING', qr: null, queueLength: 0 });
  const [showQr, setShowQr] = useState(false);

  // Batch Upload States
  const [isProcessingBatch, setIsProcessingBatch] = useState(false);
  const [batchProgress, setBatchProgress] = useState({ current: 0, total: 0, successes: 0, failed: 0, unmatched: 0 });
  const [lastBatchReport, setLastBatchReport] = useState<{ message: string, type: 'success' | 'warning' } | null>(null);

  const [searchTerm, setSearchTerm] = useState('');
  const navigate = useNavigate();

  const fetchData = useCallback(async () => {
    if (isProcessingBatch) return;

    setIsLoading(true);

    // Fetch Events first
    const eventsData = await getEvents();
    setEvents(eventsData);

    // Fetch Lists based on selected event
    const pendingData = await getPendingRequests(selectedEventId);
    setRequests(pendingData);

    const failedData = await getFailedRequests(selectedEventId);
    setFailedRequests(failedData);

    const completedData = await getCompletedRequests(selectedEventId);
    setCompletedRequests(completedData);

    const files = await getServerFiles();
    setServerFiles(files);

    setIsLoading(false);
  }, [isProcessingBatch, selectedEventId]);

  // Status Polling
  useEffect(() => {
    const statusInterval = setInterval(async () => {
        const status = await getWhatsAppStatus();
        setWaStatus(status);
        if (status.status === 'QR_READY' && !showQr) {
            // Optional: Auto popup
        }
    }, 3000);
    return () => clearInterval(statusInterval);
  }, []);

  useEffect(() => {
    fetchData();
    const interval = setInterval(fetchData, 8000);
    return () => clearInterval(interval);
  }, [fetchData]);

  const normalize = (str: string) => str.toLowerCase().replace(/[^a-z0-9]/g, '');

  const handleLogout = () => {
      localStorage.removeItem('isAuthenticated');
      navigate('/login');
  };

  const handleCreateEvent = async (e: React.FormEvent) => {
      e.preventDefault();
      if(!newEventName) return;
      await createEvent(newEventName);
      setNewEventName('');
      setShowCreateEvent(false);
      fetchData();
  };

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files;
    if (!files || files.length === 0) return;

    if (waStatus.status !== 'READY' && waStatus.status !== 'AUTHENTICATED') {
        alert("WhatsApp is not connected. Please click the WiFi icon to scan the QR code.");
        e.target.value = '';
        return;
    }

    setIsProcessingBatch(true);
    setLastBatchReport(null);
    const fileList = Array.from(files) as File[];

    // Reset stats
    setBatchProgress({ current: 0, total: fileList.length, successes: 0, failed: 0, unmatched: 0 });

    const usedRequestIds = new Set<string>();
    const tasks: { file: File, request: CustomerRequest }[] = [];
    let unmatchedCount = 0;

    // 1. Prepare Tasks (Match files to requests)
    for (const file of fileList) {
        const rawFileName = file.name;
        const nameWithoutExt = rawFileName.substring(0, rawFileName.lastIndexOf('.')) || rawFileName;
        const normFileName = normalize(nameWithoutExt);

        // Find match in queue
        // We match if the file name is contained in the requested video name OR vice versa
        // Important: check if extension matches request type? 
        // For now, loose matching on name is usually sufficient, but let's prioritize correct pending requests
        const match = requests.find(r => {
            if (usedRequestIds.has(r.id) || r.status !== 'pending') return false;
            const normVideoName = normalize(r.videoName.substring(0, r.videoName.lastIndexOf('.')) || r.videoName);
            return normFileName.includes(normVideoName) || normVideoName.includes(normFileName);
        });

        if (match) {
            usedRequestIds.add(match.id);
            tasks.push({ file, request: match });
        } else {
            unmatchedCount++;
        }
    }

    setBatchProgress(prev => ({ ...prev, unmatched: unmatchedCount }));

    // 2. Execute with High-Speed Dynamic Concurrency Pool
    const CONCURRENCY_LIMIT = 8;
    let processedCount = 0;
    let successCount = 0;
    let failCount = 0;

    const activePromises = new Set<Promise<void>>();

    for (const task of tasks) {
        const promise = (async () => {
            const success = await uploadDocument(task.request.id, task.file, task.request.phoneNumber);
            if (success) successCount++;
            else failCount++;
            processedCount++;

            setBatchProgress(prev => ({
                 ...prev,
                 current: processedCount + unmatchedCount,
                 successes: successCount,
                 failed: failCount
            }));
        })();

        activePromises.add(promise);
        promise.then(() => activePromises.delete(promise));

        if (activePromises.size >= CONCURRENCY_LIMIT) {
            await Promise.race(activePromises);
        }
    }

    await Promise.all(activePromises);

    const totalProcessed = tasks.length + unmatchedCount;
    setBatchProgress(prev => ({ ...prev, current: totalProcessed, successes: successCount, failed: failCount, unmatched: unmatchedCount }));

    const message = `Queued: ${successCount} | Unmatched: ${unmatchedCount} | Errors: ${failCount}`;
    const type = (failCount > 0 || unmatchedCount > 0) ? 'warning' : 'success';

    setLastBatchReport({ message, type });
    setIsProcessingBatch(false);
    fetchData(); 
    e.target.value = '';

    setTimeout(() => {
      setLastBatchReport(null);
      setBatchProgress({ current: 0, total: 0, successes: 0, failed: 0, unmatched: 0 });
    }, 10000);
  };

  const handleRetry = async (id: string, e: React.MouseEvent) => {
      e.stopPropagation();
      const res = await retryServerFile(id);
      if (res.success) {
          alert("Retrying... Item moved to Queue.");
          fetchData();
      } else {
          alert("Failed to retry: " + res.message);
      }
  };

  const handleDeleteRequest = async (id: string, e: React.MouseEvent) => {
      e.stopPropagation();
      if (!window.confirm("Delete this request history?")) return;
      await deleteRequest(id);
      fetchData();
  };

  const handleDeleteFile = async (filename: string, e: React.MouseEvent) => {
      e.stopPropagation();
      if (!window.confirm("Permanently delete file?")) return;
      await deleteServerFile(filename);
      fetchData();
  };

  // Helper to determine list based on tab
  const getList = () => {
      switch(activeTab) {
          case 'queue': return requests;
          case 'issues': return failedRequests;
          case 'sent': return completedRequests;
          default: return [];
      }
  };

  const listData = getList().filter(r => 
    r.customerName.toLowerCase().includes(searchTerm.toLowerCase()) ||
    r.videoName.toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <div className="flex h-screen bg-white font-sans text-slate-900 overflow-hidden relative">

      {/* MODAL: Create Event */}
      {showCreateEvent && (
