import { APP_CONFIG } from '../constants';
import { CustomerRequest, Event } from '../types';

const delay = (ms: number) => new Promise((resolve) => setTimeout(resolve, ms));

export interface ServerFile {
  name: string;
  size: string;
  created: string;
}

export interface WhatsAppStatus {
