      await createEvent(newEventName, newEventFileType);
      setNewEventName('');
      setNewEventFileType('video');
      setShowCreateEvent(false);
      fetchData();
  };

  const handleUpdateEvent = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedEventId || !newEventName) return;
    await updateEvent(selectedEventId, newEventName, newEventFileType);
    setNewEventName('');
    setNewEventFileType('video');
    setShowEditEvent(false);
    fetchData();
  };

  const handleDeleteEvent = async () => {
    if (!selectedEventId) return;
    if (!window.confirm("Are you sure you want to delete this event? This cannot be undone.")) return;
    await deleteEvent(selectedEventId);
    setSelectedEventId('');
    fetchData();
  };

  const openEditEventModal = () => {
      const ev = events.find(e => e.id === selectedEventId);
      if (ev) {
          setNewEventName(ev.name);
          setNewEventFileType(ev.defaultFileType);
          setShowEditEvent(true);
      }
  };

  // --- EDIT MODAL HANDLERS ---
  const openEditModal = (req: CustomerRequest) => {
    setEditingCustomer(req);
    setEditForm({ name: req.customerName, phone: req.phoneNumber, videoName: req.videoName });
  };

  const handleSaveEdit = async () => {
    if (!editingCustomer) return;
    const success = await updateCustomer(editingCustomer.id, editForm.name, editForm.phone, editForm.videoName);
    if (success) {
        setEditingCustomer(null);
        fetchData();
    } else {
        alert("Failed to update customer.");
    }
  };

  const handleResendFromEdit = async () => {
     if (!editingCustomer) return;
     // First save details
     await updateCustomer(editingCustomer.id, editForm.name, editForm.phone, editForm.videoName);
     // Then retry
     const res = await retryServerFile(editingCustomer.id);
     if (res.success) {
         setEditingCustomer(null);
         fetchData();
         alert("Moved to Queue for resending.");
     } else {
         alert("Failed to resend: " + res.message);
     }
  };

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files;
    if (!files || files.length === 0) return;

    if (waStatus.status !== 'READY' && waStatus.status !== 'AUTHENTICATED') {
        alert("WhatsApp is not connected. Please click the WiFi icon to scan the QR code.");
        e.target.value = '';
        return;
    }

    setIsProcessingBatch(true);
    setLastBatchReport(null);
    const fileList = Array.from(files) as File[];

    // Reset stats
    setBatchProgress({ current: 0, total: fileList.length, successes: 0, failed: 0, unmatched: 0 });

    const usedRequestIds = new Set<string>();
    const tasks: { file: File, request: CustomerRequest }[] = [];
    let unmatchedCount = 0;

    // 1. Prepare Tasks (Match files to requests)
    for (const file of fileList) {
        const rawFileName = file.name;
        const nameWithoutExt = rawFileName.substring(0, rawFileName.lastIndexOf('.')) || rawFileName;
        const normFileName = normalize(nameWithoutExt);

        // Find match in queue
        // We match if the file name is contained in the requested video name OR vice versa
        // Important: check if extension matches request type? 
        // For now, loose matching on name is usually sufficient, but let's prioritize correct pending requests
        const match = requests.find(r => {
            if (usedRequestIds.has(r.id) || r.status !== 'pending') return false;
            const normVideoName = normalize(r.videoName.substring(0, r.videoName.lastIndexOf('.')) || r.videoName);
            return normFileName.includes(normVideoName) || normVideoName.includes(normFileName);
        });

        if (match) {
            usedRequestIds.add(match.id);
            tasks.push({ file, request: match });
        } else {
            unmatchedCount++;
        }
    }

    setBatchProgress(prev => ({ ...prev, unmatched: unmatchedCount }));

    // 2. Execute with High-Speed Dynamic Concurrency Pool
    const CONCURRENCY_LIMIT = 8;
    let processedCount = 0;
    let successCount = 0;
    let failCount = 0;

    const activePromises = new Set<Promise<void>>();

    for (const task of tasks) {
        const promise = (async () => {
            const success = await uploadDocument(task.request.id, task.file, task.request.phoneNumber);
            if (success) successCount++;
            else failCount++;
            processedCount++;

            setBatchProgress(prev => ({
                 ...prev,
                 current: processedCount + unmatchedCount,
                 successes: successCount,
                 failed: failCount
            }));
        })();

        activePromises.add(promise);
        promise.then(() => activePromises.delete(promise));

        if (activePromises.size >= CONCURRENCY_LIMIT) {
            await Promise.race(activePromises);
        }
    }

    await Promise.all(activePromises);

    const totalProcessed = tasks.length + unmatchedCount;
    setBatchProgress(prev => ({ ...prev, current: totalProcessed, successes: successCount, failed: failCount, unmatched: unmatchedCount }));

    const message = `Queued: ${successCount} | Unmatched: ${unmatchedCount} | Errors: ${failCount}`;
    const type = (failCount > 0 || unmatchedCount > 0) ? 'warning' : 'success';

    setLastBatchReport({ message, type });
    setIsProcessingBatch(false);
    fetchData(); 
    e.target.value = '';

    setTimeout(() => {
      setLastBatchReport(null);
      setBatchProgress({ current: 0, total: 0, successes: 0, failed: 0, unmatched: 0 });
    }, 10000);
  };

  const handleRetry = async (id: string, e: React.MouseEvent) => {
      e.stopPropagation();
      const res = await retryServerFile(id);
      if (res.success) {
          alert("Retrying... Item moved to Queue.");
          fetchData();
      } else {
          alert("Failed to retry: " + res.message);
      }
  };

  const handleDeleteRequest = async (id: string, e: React.MouseEvent) => {
      e.stopPropagation();
      if (!window.confirm("Delete this request history?")) return;
      await deleteRequest(id);
      fetchData();
