// Export CSV
app.get('/export-csv', async (req, res) => {
    try {
        const { type, eventId } = req.query;
        // type should be 'completed' or 'failed'
        const query = { status: type };
        if (eventId) query.eventId = eventId;

        const docs = await Customer.find(query).sort({ requestedAt: -1 });

        const fields = ['customerName', 'phoneNumber', 'videoName', 'status', 'requestedAt', 'completedAt', 'error'];
        const csvRows = [
            fields.join(','), // Header
            ...docs.map(d => fields.map(f => {
                let val = d[f] ? d[f].toString() : '';
                val = val.replace(/"/g, '""'); // Escape double quotes
                return `"${val}"`;
            }).join(','))
        ];

        const csvContent = csvRows.join('\n');

        res.header('Content-Type', 'text/csv');
        res.attachment(`${type}_${eventId || 'all'}_${Date.now()}.csv`);
        res.send(csvContent);
    } catch (e) {
        res.status(500).send("Error generating CSV");
    }
});

// Upload & Queue
app.post('/upload-document', upload.single('file'), async (req, res) => {
  if (!req.file) return res.status(400).json({ error: 'No file.' });

  const { requestId } = req.body; // phoneNumber and videoName will be fetched from DB for consistency

  // Update DB to Processing AND SAVE FILEPATH for retention
  const customer = await Customer.findByIdAndUpdate(requestId, { 
      status: 'processing',
      filePath: req.file.path
  }, { new: true }).populate('eventId');

  if (!customer) {
      return res.status(404).json({ error: 'Customer request not found' });
  }

  // Generate Caption
  let caption = `Hello ${customer.customerName}! Here is your document: ${customer.videoName}`;
  if (customer.eventId && customer.eventId.messageTemplate) {
      caption = customer.eventId.messageTemplate
          .replace(/{{name}}/g, customer.customerName)
          .replace(/{{filename}}/g, customer.videoName);
  }

  // Add to Queue
  messageQueue.push({
      requestId: customer._id,
      phoneNumber: customer.phoneNumber,
      customerName: customer.customerName,
      videoName: customer.videoName,
      filePath: req.file.path,
      caption: caption
  });

  // Trigger Processor
  processQueue();

  res.json({ success: true, message: 'Queued for safe sending' });
});

