// Retry Request
app.post('/retry-request/:id', async (req, res) => {
    try {
        const doc = await Customer.findById(req.params.id).populate('eventId');
        if (!doc) return res.status(404).json({ error: 'Request not found' });

        // If filePath is stored in doc, check that first
        let filePath = doc.filePath;

        if (!filePath || !fs.existsSync(filePath)) {
            // Fallback to name matching if path is missing (legacy support)
            const files = fs.readdirSync(uploadDir);
            const normalize = (s) => s.toLowerCase().replace(/[^a-z0-9]/g, '');
            const target = normalize(doc.videoName);

            // STRICT MATCH ONLY (Fixes similar name issue on retry)
            // Note: target usually has extension (e.g. 001mp4) because Register form adds it.
            // Multer preserves extensions on upload.
            const match = files.find(f => normalize(f) === target);

            if (match) {
                filePath = path.join(uploadDir, match);
                // Update doc with found path
                doc.filePath = filePath;
            } else {
                return res.status(400).json({ error: 'File missing from server storage.' });
            }
        }

        // Generate Caption
        let caption = `Hello ${doc.customerName}! Here is your document: ${doc.videoName}`;
        if (doc.eventId && doc.eventId.messageTemplate) {
            caption = doc.eventId.messageTemplate
                .replace(/{{name}}/g, doc.customerName)
                .replace(/{{filename}}/g, doc.videoName);
        }

        // Reset Status
        doc.status = 'processing';
        doc.error = null;
        await doc.save();

        // Push to Queue
        messageQueue.push({
            requestId: doc._id,
            phoneNumber: doc.phoneNumber,
            customerName: doc.customerName,
            videoName: doc.videoName,
            filePath: filePath,
            caption: caption
        });

        processQueue();

        res.json({ success: true });
    } catch (e) {
        res.status(500).json({ error: e.message });
    }
});

